// Fail-closed gate. Same shape as every other VIO webhook: the secret is in the URL or
// the x-vio-token header, and it is validated before anything else runs.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {}; const h = item.headers || {};
const got = q.t || q.token || h['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || {} };

// Report what Supabase actually answered, so this is proof rather than a green tick.
//
// n8n's credential store says "successfully imported" for a credential that cannot connect,
// exactly as `n8n import:workflow` says "successfully imported" for code the running server
// will never load. This workflow exists so the Postgres credential has to demonstrate itself.
const rows = $input.all().map((i) => i.json || {});
const byTable = {};
for (const r of rows) if (r.table) byTable[r.table] = Number(r.n);
return [{ json: {
  ok: rows.length > 0,
  reached: 'supabase (aws-0-us-west-2 pooler, session mode)',
  tables: byTable,
  suppression_guard: rows.find((r) => r.table === '_guard')?.n ?? null,
  at: new Date().toISOString(),
} }];
